namespace HRM.Models.Recruitment;

/// <summary>Source-backed recruitment policy profile; CSC requirements remain configuration, not hardcoded rules.</summary>
public sealed class RecruitmentPolicyProfile { public int Id { get; set; } public string Code { get; set; } = string.Empty; public string Name { get; set; } = string.Empty; public string Jurisdiction { get; set; } = "Maldives"; public bool IsCscProfile { get; set; } public bool IsActive { get; set; } = true; public int Version { get; set; } = 1; }

/// <summary>Effective-dated policy version. It can be used only after authoritative-source verification.</summary>
public sealed class RecruitmentPolicyVersion { public int Id { get; set; } public int RecruitmentPolicyProfileId { get; set; } public string VersionCode { get; set; } = string.Empty; public string OfficialSourceUrl { get; set; } = string.Empty; public string OfficialSourceReference { get; set; } = string.Empty; public DateTime EffectiveFrom { get; set; } public DateTime? EffectiveTo { get; set; } public string VerificationStatus { get; set; } = "PendingVerification"; public int? VerifiedByUserId { get; set; } public DateTime? VerifiedAtUtc { get; set; } public bool IsApprovedForUse { get; set; } public int Version { get; set; } = 1; public RecruitmentPolicyProfile RecruitmentPolicyProfile { get; set; } = null!; }

/// <summary>Traceable CSC or other policy rule. Only verified rules may become mandatory checks.</summary>
public sealed class RecruitmentComplianceRule { public int Id { get; set; } public int RecruitmentPolicyVersionId { get; set; } public string RuleCode { get; set; } = string.Empty; public string Requirement { get; set; } = string.Empty; public string OfficialProvision { get; set; } = string.Empty; public string RecruitmentType { get; set; } = "All"; public string PositionCategory { get; set; } = "All"; public string EnforcementLevel { get; set; } = "Advisory"; public string ValidationDefinitionJson { get; set; } = "{}"; public string ResponsibleAuthority { get; set; } = string.Empty; public string VerificationStatus { get; set; } = "PendingVerification"; public bool IsActive { get; set; } = true; public int Version { get; set; } = 1; public RecruitmentPolicyVersion RecruitmentPolicyVersion { get; set; } = null!; }

/// <summary>Organisation policy selection; future requisitions and vacancies will snapshot this version.</summary>
public sealed class RecruitmentPolicyAssignment { public int Id { get; set; } public int OrganisationId { get; set; } public int RecruitmentPolicyVersionId { get; set; } public string RecruitmentType { get; set; } = "CivilService"; public string PositionCategory { get; set; } = "All"; public DateTime EffectiveFrom { get; set; } public DateTime? EffectiveTo { get; set; } public bool IsActive { get; set; } = true; public int Version { get; set; } = 1; public int OperationLogId { get; set; } public RecruitmentPolicyVersion RecruitmentPolicyVersion { get; set; } = null!; }
